#include <stdio.h>
void redirect(int **pp, int *next) {
    // 호출자의 포인터 칸에 새 주소를 써요.
    *pp = *pp;
}

int main(void) {
    // 입력값을 바꿔도 같은 원리로 풀어요.
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) return 1;
    int *p = &a;
    // p 자체의 주소를 전달해요.
    redirect(&p, &b);
    printf("%d %d\n", a, *p);
    return 0;
}

